-- Queer Atlas: Calgary city package
-- Editorially checked 2026-08-14. Idempotent; no null coordinates.

begin;

with src as (
select * from jsonb_to_recordset($calgary_places$
[
 {"name":"Twisted Element","city":"calgary","type":"club","description":"Calgary's largest dedicated queer nightclub pairs an early drag show with a two-level dance party that runs into the small hours. The venue publishes unusually clear policies: no dress code, all-gender washrooms, zero tolerance for harassment, naloxone-trained staff and no guest list. The heritage building is not wheelchair accessible, an important limitation to know before committing to the night.","vibe":"big-hearted queer club where drag gives way to a packed two-floor dance night","hours":"Event-led. Friday and Saturday typically open around 20:00, with drag near 21:30 and dancing until about 03:00; verify the live calendar.","link":"https://twistedelement.club/","location":"1006 11 Avenue SW, Calgary, AB T2R 0G3, Canada","lat":51.04310,"lng":-114.08550},
 {"name":"Texas Lounge","city":"calgary","type":"bar","description":"A tiny gay dive bar behind the Model Milk building, serving Calgary's LGBTQ+ community since 1987. Known locally as The Bunker, it is more about inexpensive drinks, karaoke, VLTs and seeing familiar faces than a polished cocktail production. The single-room scale is part of the charm, but Pride nights can become uncomfortably cramped.","vibe":"old-school gay dive with warm bartenders, karaoke and an older local rhythm","hours":"Monday-Thursday 15:00-late; Friday 14:00-03:00; Saturday and Sunday 11:00-03:00, according to the official site.","link":"https://www.texaslounge.ca/","location":"Rear parking-lot entrance, 308B 17 Avenue SW, Calgary, AB T2S 0A8, Canada","lat":51.03750,"lng":-114.07090},
 {"name":"Goliaths Saunatel","city":"calgary","type":"sauna","description":"Calgary's long-running private men's bathhouse shares its discreet rear entrance and building with Texas Lounge. The 24-hour venue has lockers, rooms, steam, sauna, hot tub and adult play areas, with membership and photo ID required. Recent visitors consistently separate the friendly reception from facilities they describe as dated, so arrive for the social institution rather than luxury-spa polish.","vibe":"historic men-only bathhouse with friendly reception and an older-skewing crowd","hours":"Open 24 hours daily according to the current official and specialist listings; confirm maintenance closures and event access.","link":"https://www.goliathsyyc.ca/","location":"Rear parking-lot entrance, 308B 17 Avenue SW, Calgary, AB T2S 0A8, Canada","lat":51.03750,"lng":-114.07090},
 {"name":"Infinity Ultra Lounge","city":"calgary","type":"bar","description":"A compact underground LGBTQ+ lounge under the Grain Exchange Building, programming drag, burlesque, live music and local performers rather than operating as a generic seven-night club. Its own language is deliberately broad: a gay bar that wants a diverse room and welcomes everyone. Check the event first, because an ordinary weekend lounge and a produced show are very different experiences.","vibe":"intimate basement stage for drag, burlesque and inclusive late-week drinks","hours":"Friday and Saturday 21:00-02:00; earlier opening for special events. Private bookings on other dates.","link":"https://www.infinityultralounge.com/","location":"811 1 Street SW, Calgary, AB, Canada","lat":51.04515,"lng":-114.06553},
 {"name":"Dickens Pub","city":"calgary","type":"bar","description":"A basement live-music institution whose metal, goth and alternative calendar regularly makes room for queer dance parties, drag competitions and major Pride shows. It is not a permanent gay bar, but locals repeatedly place it on the real queer map because the staff, crowd and promoters make difference feel ordinary. Strong sound, good alcohol-free choices and a slightly hidden parking-lot entrance are recurring practical notes.","vibe":"grungy, generous basement venue where queer pop-ups meet Calgary's alternative scene","hours":"Hours follow the event calendar; doors are commonly 18:00 or later. Use the ticket listing for the exact show.","link":"https://dickensyyc.com/","location":"1000 9 Avenue SW, Calgary, AB T2P 2Y6, Canada","lat":51.04530,"lng":-114.08410},
 {"name":"The Attic Bar and Stage","city":"calgary","type":"restaurant","description":"A second-floor Inglewood room combining an entirely plant-based Italian menu with drag brunch, queer and femme-curated comedy, burlesque, jazz and live performance. It is home to the long-running Carly's Angels and operates with an explicit no-hate-speech standard. Come for a named show or a thoughtful dinner rather than assuming every service is a drag event.","vibe":"velvet-soft vegan supper club with queer performance at the heart of its calendar","hours":"Thursday 17:00-21:00; Friday-Saturday 17:00-22:00; Sunday 17:00-21:00, plus separately ticketed brunches; Monday-Wednesday closed.","link":"https://www.theatticyyc.ca/","location":"Second floor, 1413 9 Avenue SE, Calgary, AB, Canada","lat":51.04010,"lng":-114.03080},
 {"name":"Ship and Anchor Pub","city":"calgary","type":"bar","description":"A 17th Avenue institution rather than a gay bar, but one with a long, visible record of drag shows, queer-charity work, Pride flags and gender-neutral washrooms. The patio can be one of the easiest mixed social rooms in Calgary: punks, service workers, students, older regulars and queer groups overlap without much ceremony. Sports and Stampede crowds can temporarily change that balance.","vibe":"busy neighbourhood pub where queer Calgary mixes naturally with the wider city","hours":"Monday-Friday 11:00-02:00; Saturday 10:00-02:00; Sunday 09:00-02:00.","link":"https://shipandanchor.com/","location":"534 17 Avenue SW, Calgary, AB T2S 0B1, Canada","lat":51.03770,"lng":-114.07350},
 {"name":"Congress Coffee Company","city":"calgary","type":"cafe","description":"A north-east coffeehouse that behaves more like a community arts room: live music, drag, queer open mics, workshops and small social events share space with daytime regulars. Its rental policy explicitly rejects exclusion based on sexual or gender identity. The programme makes it valuable for sober connection, though it is a mixed cafe and the queer signal rises and falls with the calendar.","vibe":"warm, art-filled community cafe for sober hangs, small shows and queer creativity","hours":"Current listings: Monday-Tuesday 07:00-17:00; Wednesday-Thursday 07:00-21:00; Friday 07:00-22:00; Saturday 09:00-22:00; Sunday 09:00-17:00. Confirm live events.","link":"https://www.congresscoffeeshop.com/","location":"Bay 8, #1A 215 36 Avenue NE, Calgary, AB T2E 2L4, Canada","lat":51.08370,"lng":-114.05970},
 {"name":"Hyatt Regency Calgary","city":"calgary","type":"hotel","description":"A mainstream downtown hotel with a concrete queer-community role as host of the annual Centre for Sexuality Pride Brunch. The central location is practical for the parade, Stephen Avenue and CTrain, while the pool and full-service format suit travellers who want polish rather than scene immersion. Pride partnership is documented; it should not be mistaken for an exclusively LGBTQ+ property.","vibe":"central full-service stay with a meaningful Pride-brunch connection","hours":"Hotel reception operates 24 hours; restaurants, spa, pool and event access follow their own schedules.","link":"https://www.hyatt.com/hyatt-regency/en-US/calrc-hyatt-regency-calgary","location":"700 Centre Street SE, Calgary, AB T2G 5P6, Canada","lat":51.04620,"lng":-114.06300}
]
$calgary_places$) p(name text,city text,type text,description text,vibe text,hours text,link text,location text,lat double precision,lng double precision)
), upd as (
 update public.places p set type=s.type,description=s.description,vibe=s.vibe,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
 from src s where lower(trim(p.city))=s.city and lower(trim(p.name))=lower(trim(s.name)) returning p.id
)
insert into public.places(name,city,type,description,vibe,vibe_tags,hours,link,location,lat,lng,seo_indexable,seo_quality_status,updated_at)
select name,city,type,description,vibe,array[]::text[],hours,link,location,lat,lng,true,'approved',timezone('utc',now()) from src s
where not exists(select 1 from public.places p where lower(trim(p.city))=s.city and lower(trim(p.name))=lower(trim(s.name)));

with src as (
select * from jsonb_to_recordset($calgary_events$
[
 {"name":"Calgary Pride Week 2026","city":"calgary","description":"Calgary Pride's new citywide edition spreads queer arts, culture, gathering and advocacy across seven programme threads instead of one fenced festival site. The week runs from 31 August through 6 September, ending with the downtown parade and Pride on the Island.","link":"https://calgarypride.ca/pride-2026/","date":"2026-08-31","start_date":"2026-08-31","end_date":"2026-09-06","location":"Venues across Calgary, Alberta, Canada","lat":51.04470,"lng":-114.07190,"vibe":"citywide queer culture, public celebration and community connection"},
 {"name":"Calgary Pride Flag Raising 2026","city":"calgary","description":"Pride Week opens with a public flag raising at The Confluence Historic Site and Parkland on Monday 31 August from 11:00 to 13:00. It is a civic, daytime beginning to a week that later moves into nightlife, arts and the parade.","link":"https://calgarypride.ca/events/","date":"2026-08-31","start_date":"2026-08-31","end_date":"2026-08-31","location":"The Confluence Historic Site and Parkland, 750 9 Avenue SE, Calgary, AB, Canada","lat":51.04440,"lng":-114.04400,"vibe":"public, ceremonial and accessible opening to Pride Week"},
 {"name":"End of the Rainbow Pride Patio Party 2026","city":"calgary","description":"A Pride Monday patio gathering at Cold Garden on 31 August from 18:00 to 22:00, connecting the brewery's open social energy with End of the Rainbow's work alongside LGBTQ+ newcomers and refugees. Treat it as a community fundraiser and mixer, not a generic branded beer night.","link":"https://calgarypride.ca/events/","date":"2026-08-31","start_date":"2026-08-31","end_date":"2026-08-31","location":"Cold Garden Beverage Company, 1100 11 Street SE, Calgary, AB, Canada","lat":51.04190,"lng":-114.03620,"vibe":"easy patio conversation supporting queer newcomer community"},
 {"name":"Yvie Oddly's Odd Ball 2026","city":"calgary","description":"The Cabaret Company brings Yvie Oddly to Dickens on Friday 4 September for a drag and designer competition running from 19:00 to 23:30. The basement setting should make this feel closer to Calgary's alternative performance culture than a polished theatre tour stop.","link":"https://calgarypride.ca/events/","date":"2026-09-04","start_date":"2026-09-04","end_date":"2026-09-04","location":"Dickens Pub, 1000 9 Avenue SW, Calgary, AB T2P 2Y6, Canada","lat":51.04530,"lng":-114.08410,"vibe":"high-concept drag, local design and underground-club energy"},
 {"name":"Calgary Pride Queer Arts Market 2026","city":"calgary","description":"A free indoor Pride marketplace created with Queer Calgary and HoliGay Events, filling BMO Centre Hall F with queer artists and vendors on Saturday 5 September from 11:00 to 19:00. The event is wheelchair accessible and deliberately useful before the parade weekend's nighttime programme.","link":"https://calgarypride.ca/pride-2026/","date":"2026-09-05","start_date":"2026-09-05","end_date":"2026-09-05","location":"BMO Centre Hall F, 20 Roundup Way SE, Calgary, AB, Canada","lat":51.03720,"lng":-114.05180,"vibe":"free queer makers' market with practical, all-day Pride energy"},
 {"name":"Centre for Sexuality Pride Brunch 2026","city":"calgary","description":"The annual Pride Brunch returns to Hyatt Regency Calgary on Saturday 5 September from 10:30 to 13:30. Drag, speakers and community fundraising support Camp fYrefly Southern Alberta, with individual tickets listed at CAD 75 and tables of eight at CAD 800.","link":"https://www.showpass.com/pride-brunch-2026/","date":"2026-09-05","start_date":"2026-09-05","end_date":"2026-09-05","location":"Hyatt Regency Calgary, 700 Centre Street SE, Calgary, AB T2G 5P6, Canada","lat":51.04620,"lng":-114.06300,"vibe":"polished community brunch funding queer youth leadership"},
 {"name":"Pride on the Island 2026","city":"calgary","description":"Prince's Island Park becomes Pride's outdoor performance hub on 5 and 6 September, with drag, DJs, comedy and local artists across the weekend. This is the broad, public festival feeling in the new citywide model, but exact stage times and access information should be checked before leaving.","link":"https://calgarypride.ca/pride-2026/pride-on-the-island/","date":"2026-09-05","start_date":"2026-09-05","end_date":"2026-09-06","location":"Prince's Island Park, Calgary, AB, Canada","lat":51.05550,"lng":-114.07060,"vibe":"open-air queer performance and all-ages Pride-weekend gathering"},
 {"name":"Calgary Pride Parade 2026","city":"calgary","description":"The parade returns downtown on Sunday 6 September, travelling east along 9 Avenue SW from 5 Street SW to 4 Street SE. The official start time remains TBA, so use the live parade page rather than an old route graphic when planning arrival and accessible viewing.","link":"https://calgarypride.ca/pride-2026/pride-parade/","date":"2026-09-06","start_date":"2026-09-06","end_date":"2026-09-06","location":"9 Avenue SW from 5 Street SW to 4 Street SE, downtown Calgary, AB, Canada","lat":51.04510,"lng":-114.07350,"vibe":"large downtown march balancing celebration, protest and civic visibility"}
]
$calgary_events$) e(name text,city text,description text,link text,date date,start_date date,end_date date,location text,lat double precision,lng double precision,vibe text)
), upd as (
 update public.events e set description=s.description,link=s.link,date=s.date,start_date=s.start_date,end_date=s.end_date,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
 from src s where lower(trim(e.city))=s.city and lower(trim(e.name))=lower(trim(s.name)) returning e.id
)
insert into public.events(name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,seo_indexable,seo_quality_status,updated_at)
select name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],true,'approved',timezone('utc',now()) from src s
where not exists(select 1 from public.events e where lower(trim(e.city))=s.city and lower(trim(e.name))=lower(trim(s.name)));

with src as (
select * from jsonb_to_recordset($calgary_services$
[
 {"name":"Skipping Stone Foundation","city":"calgary","type":"wellness","provider_name":"Skipping Stone Foundation","contact":"587-333-4342; info@skippingstone.ca","booking_link":"https://skippingstone.janeapp.com/locations/skipping-stone-foundation/book","description":"A community-led hub for trans, Two-Spirit and gender-diverse people of all ages and their families. One-to-one support, systems navigation, name and gender-marker help, affirming gear, health connections, groups, voice support and youth and adult programmes sit under one roof.","hours":"Tuesday-Friday 09:00-17:00 or by appointment.","link":"https://www.skippingstone.ca/","location":"Suite 1900, 736 6 Avenue SW, Calgary, AB T2P 3T7, Canada","lat":51.04850,"lng":-114.07890,"price_tier":"$","vibe":"practical trans-led care with dignity, family support and long-term community","source":"Skipping Stone official programmes, contact and booking pages; checked 2026-08-14"},
 {"name":"Centre for Sexuality","city":"calgary","type":"wellness","provider_name":"Centre for Sexuality","contact":"403-283-5580; intake@centreforsexuality.ca","booking_link":"https://www.centreforsexuality.ca/","description":"A long-established sexual-health and relationship organisation offering education, training, counselling and targeted services for LGBTQ+ communities. Current outreach includes confidential STI testing windows for everyone and specific sessions for gay, bisexual and other men who have sex with men, including trans and gender-diverse people.","hours":"Office Monday-Friday 09:00-17:00, closed 12:00-13:00. Testing and counselling use separate current schedules.","link":"https://www.centreforsexuality.ca/","location":"Suite 700, 1509 Centre Street South, Calgary, AB T2G 2E6, Canada","lat":51.03900,"lng":-114.06270,"price_tier":"$","vibe":"confidential sexual-health care and education without moralising","source":"Centre for Sexuality and SafeLink Alberta current service pages; checked 2026-08-14"},
 {"name":"SafeLink Alberta Calgary","city":"calgary","type":"wellness","provider_name":"SafeLink Alberta","contact":"403-508-2500; calgaryclinic@safelinkalberta.ca; testing text 403-508-2716","booking_link":"https://www.safelinkalberta.ca/testing-prevention/testing","description":"Low-barrier HIV and STI testing, harm reduction, safer-sex supplies, naloxone, peer support and health-system navigation from the organisation formerly known as AIDS Calgary. The office has gender-neutral washrooms, but it is on the second floor and accessible only by stairs.","hours":"Monday-Friday 09:00-12:00 by appointment; Monday and Wednesday-Friday 13:00-16:00 drop-in. Testing clinic Tuesday-Thursday by appointment.","link":"https://safelinkalberta.ca/contact-us/","location":"Suite 201, 1950 10 Avenue SW, Calgary, AB T3C 0J8, Canada","lat":51.04420,"lng":-114.10520,"price_tier":"$","vibe":"non-judgmental testing and harm reduction grounded in queer community history","source":"SafeLink Alberta official contact, testing and Calgary support pages; checked 2026-08-14"},
 {"name":"End of the Rainbow Foundation","city":"calgary","type":"other","provider_name":"End of the Rainbow Foundation","contact":"403-262-4086; appointments via official contact form","booking_link":"https://endoftherainbow.ca/calgary-lgbtq-refugee-centre/","description":"One-to-one settlement support, referrals and community connection for LGBTQ+ asylum seekers, refugees and newcomers. The foundation clearly states that it does not write letters attesting to a person's LGBTQ+ identity; refugee sponsorship requests must use its formal review process rather than ordinary email.","hours":"Refugee Centre appointments Monday-Friday 10:00-17:00; arrange in advance.","link":"https://endoftherainbow.ca/","location":"Suite 400, 750 11 Street SW, Calgary, AB T2P 3N7, Canada","lat":51.04720,"lng":-114.08860,"price_tier":"$","vibe":"careful newcomer support connecting queer refugees to real settlement pathways","source":"End of the Rainbow official contact and Calgary LGBTQ+ Refugee Centre pages; checked 2026-08-14"},
 {"name":"Aura Youth Housing","city":"calgary","type":"other","provider_name":"Trellis Society","contact":"Housing Liaison: housing@growwithtrellis.ca; SORCe assessment 587-779-5015","booking_link":"https://www.growwithtrellis.ca/housing-support-shelter/youth-housing/","description":"Housing-first support for 2SLGBTQIA+, non-binary and gender-nonconforming young people aged 14 to 24 who are experiencing or at risk of homelessness. Aura includes scattered-site support and Iris Place; access begins with an eligibility assessment rather than a public walk-in at a protected residence.","hours":"Assessment access follows current SORCe hours; housing support is programme-based and protected addresses are not public.","link":"https://www.growwithtrellis.ca/housing-support-shelter/youth-housing/","location":"Access assessment through SORCe, 1944 10 Avenue SW, Calgary, AB, Canada; residence addresses protected","lat":51.04420,"lng":-114.10500,"price_tier":"$","vibe":"affirming housing support centred on queer youth stability and choice","source":"Trellis Society official Youth Housing page and 211 Alberta Aura access record; checked 2026-08-14"}
]
$calgary_services$) s(name text,city text,type text,provider_name text,contact text,booking_link text,description text,hours text,link text,location text,lat double precision,lng double precision,price_tier text,vibe text,source text)
), upd as (
 update public.services x set type=s.type,provider_name=s.provider_name,contact=s.contact,booking_link=s.booking_link,description=s.description,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,price_tier=s.price_tier,vibe=s.vibe,source=s.source,"lastChecked"='2026-08-14'::date,verified=true,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
 from src s where lower(trim(x.city))=s.city and lower(trim(x.name))=lower(trim(s.name)) returning x.id
)
insert into public.services(name,city,type,provider_name,contact,booking_link,description,hours,link,image_urls,location,lat,lng,price_tier,vibe,vibe_tags,source,"lastChecked",verified,seo_indexable,seo_quality_status,updated_at)
select name,city,type,provider_name,contact,booking_link,description,hours,link,array[]::text[],location,lat,lng,price_tier,vibe,array[]::text[],source,'2026-08-14'::date,true,true,'approved',timezone('utc',now()) from src s
where not exists(select 1 from public.services x where lower(trim(x.city))=s.city and lower(trim(x.name))=lower(trim(s.name)));

commit;

select 'places' category,count(*) total from public.places where lower(trim(city))='calgary'
union all select 'events',count(*) from public.events where lower(trim(city))='calgary'
union all select 'services',count(*) from public.services where lower(trim(city))='calgary'
order by category;
